def key = null;
if (ctx.auditd != null) {
  if (ctx.auditd.log != null && ctx.auditd.log.key != null) { key = ctx.auditd.log.key; }
  else if (ctx.auditd.data != null && ctx.auditd.data.key != null) { key = ctx.auditd.data.key; }
}
if (key == null && ctx.tags instanceof List) {
  for (def t : ctx.tags) {
    if (t instanceof String && ((String) t).startsWith('soc_')) { key = t; break; }
  }
}
if (key != null) {
  if (ctx.soc == null) { ctx.soc = new HashMap(); }
  ctx.soc.rule_key = key;
}
